begin;
create extension if not exists pgtap with schema extensions;
select plan(19);
insert into public.organizations(id,name) values('10000000-0000-0000-0000-000000000071','Checkout A'),('10000000-0000-0000-0000-000000000072','Checkout B');
insert into public.locations(id,organization_id,name,slug,checkout_delivery_fee) values('20000000-0000-0000-0000-000000000071','10000000-0000-0000-0000-000000000071','Checkout Location A','checkout-a',5),('20000000-0000-0000-0000-000000000072','10000000-0000-0000-0000-000000000072','Checkout Location B','checkout-b',9);
insert into public.categories(id,location_id,name,slug) values('30000000-0000-0000-0000-000000000071','20000000-0000-0000-0000-000000000071','Meals','meals');
insert into public.products(id,location_id,category_id,name,slug,base_price) values('40000000-0000-0000-0000-000000000071','20000000-0000-0000-0000-000000000071','30000000-0000-0000-0000-000000000071','Meal','meal',20);
select ok(not has_table_privilege('anon','public.checkout_sessions','select'),'anon cannot select checkouts');
select ok(not has_table_privilege('anon','public.checkout_commands','select'),'anon cannot list commands');
select ok(has_function_privilege('anon','public.start_public_checkout(text,uuid)','execute'),'anon has only scoped checkout RPC');
set local role anon;
create temporary table carts as select public.create_public_cart('checkout-a') value;
create temporary table carts_b as select public.create_public_cart('checkout-b') value;
create temporary table added as select public.mutate_public_cart((select value->>'publicToken' from carts),0,'90000000-0000-0000-0000-000000000071','{"type":"ADD","productId":"40000000-0000-0000-0000-000000000071","modifierOptionIds":[],"quantity":2}') value;
create temporary table checkouts as select public.start_public_checkout((select value->>'publicToken' from carts),'91000000-0000-0000-0000-000000000071') value;
select is(value->>'status','IN_PROGRESS','starts checkout for active cart') from checkouts;
select throws_ok($$select public.start_public_checkout('ffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffff','91000000-0000-0000-0000-000000000072')$$,'P0001','CHECKOUT_NOT_FOUND','invalid token reveals no checkout');
select is(public.get_public_checkout((select value->>'publicToken' from carts_b)) is null,true,'token B cannot access checkout A');
create temporary table customer as select public.mutate_public_checkout((select value->>'publicToken' from carts),0,'92000000-0000-0000-0000-000000000071','{"type":"CUSTOMER","name":"Ana Silva","phone":"11999999999"}') value;
select is(value->>'revision','1','customer update increments revision') from customer;
create temporary table fulfillment as select public.mutate_public_checkout((select value->>'publicToken' from carts),1,'92000000-0000-0000-0000-000000000072','{"type":"FULFILLMENT","fulfillmentType":"DELIVERY"}') value;
select is(value->>'fulfillmentType','DELIVERY','selects delivery') from fulfillment;
create temporary table addressed as select public.mutate_public_checkout((select value->>'publicToken' from carts),2,'92000000-0000-0000-0000-000000000073','{"type":"ADDRESS","address":{"postalCode":"01001000","street":"Praca da Se","number":"1","neighborhood":"Se","city":"Sao Paulo","state":"SP"}}') value;
select is(value->>'revision','3','address update is versioned') from addressed;
create temporary table ready as select public.mutate_public_checkout((select value->>'publicToken' from carts),3,'92000000-0000-0000-0000-000000000074','{"type":"VALIDATE"}') value;
select is(value->>'status','READY','authoritative validation marks ready') from ready;
select is(value->>'subtotal','40.00','client never defines authoritative subtotal') from ready;
select is(value->>'total','45.00','server fee boundary computes total') from ready;
select is(value->>'cartRevisionValidated','1','ready records validated cart revision') from ready;
select is(public.mutate_public_checkout((select value->>'publicToken' from carts),3,'92000000-0000-0000-0000-000000000074','{"type":"CANCEL"}')->>'status','READY','validate retry returns cached response') ;
select throws_ok($$select public.mutate_public_checkout((select value->>'publicToken' from carts),3,'92000000-0000-0000-0000-000000000075','{"type":"CUSTOMER","name":"Other","phone":"11999999999"}')$$,'P0001','CHECKOUT_REVISION_CONFLICT','stale checkout revision is rejected');
create temporary table changed_cart as select public.mutate_public_cart((select value->>'publicToken' from carts),1,'93000000-0000-0000-0000-000000000071',jsonb_build_object('type','UPDATE','itemId',(select value->'items'->0->>'id' from added),'productId','40000000-0000-0000-0000-000000000071','modifierOptionIds','[]'::jsonb,'quantity',1)) value;
select is(public.get_public_checkout((select value->>'publicToken' from carts))->>'status','IN_PROGRESS','cart mutation invalidates ready checkout');
select is(public.get_public_checkout((select value->>'publicToken' from carts))->>'cartRevisionValidated',null,'invalidated checkout forgets cart revision');
reset role;update public.products set base_price=25 where id='40000000-0000-0000-0000-000000000071';set local role anon;
select is(public.mutate_public_checkout((select value->>'publicToken' from carts),4,'92000000-0000-0000-0000-000000000076','{"type":"VALIDATE"}')->>'outcome','PRICE_CHANGED','price change is explicit and not silently accepted');
reset role;
select throws_ok($$insert into public.checkout_sessions(location_id,cart_id) values('20000000-0000-0000-0000-000000000071',(select id from public.carts where location_id='20000000-0000-0000-0000-000000000072'))$$,'23503',null,'composite FK rejects cross-location cart');
select * from finish();rollback;
